sys_script.script:
(function executeRule(current, previous) {

    var roleUpper = (current.getValue('u_role') || '').toUpperCase().trim();
    var tshRoles = ['TSH', 'TSH_BPD', 'TSM'];

    if (tshRoles.indexOf(roleUpper) === -1) {
        return;
    }

    if (current.operation() !== 'insert' && !current.u_user.changes()) {
        return;
    }

    var segment = current.getValue('u_segment') || '';
    var zone = current.getValue('u_zone') || '';
    var region = current.getValue('u_region') || '';
    var depot = current.getValue('u_depot') || '';
    var newUserId = current.getValue('u_user') || '';

    var tsh = new GlideRecord('x_birl3_clm_tsh');
    tsh.addQuery('u_role', roleUpper);
    tsh.addQuery('segment', segment);
    tsh.addQuery('zone', zone);
    tsh.addQuery('region', region);
    if (roleUpper !== 'TSM') {
        tsh.addQuery('depot', depot);
    }
    tsh.query();

    if (tsh.next()) {
        tsh.setValue('name', newUserId);
        tsh.update();
        gs.info('CLM: TSH updated for role=' + roleUpper + ', segment=' + segment +
                ', zone=' + zone + ', region=' + region + ', depot=' + depot);
    } else {
        var newTsh = new GlideRecord('x_birl3_clm_tsh');
        newTsh.initialize();
        newTsh.setValue('name', newUserId);
        newTsh.setValue('u_role', roleUpper);
        newTsh.setValue('zone', zone);
        newTsh.setValue('zone_name', current.getValue('u_zone_name') || '');
        newTsh.setValue('region', region);
        newTsh.setValue('region_name', current.getValue('u_region_name') || '');
        newTsh.setValue('depot', roleUpper !== 'TSM' ? depot : '');
        newTsh.setValue('segment', segment);
        newTsh.insert();
        gs.info('CLM: TSH created proactively for role=' + roleUpper + ', segment=' + segment);
    }

})(current, previous);
